public boolean hurtServer(ServerLevel level, DamageSource source, float amount) {
	if (this.getRandom().nextInt(2) == 0) {
		AreaEffectCloud cloud = new AreaEffectCloud(this.level(), this.getX(), this.getY(), this.getZ());

		cloud.setCustomParticle(UGParticleTypes.GLOOMPER_FART.get());
		cloud.setRadius(3.0F);
		cloud.setDuration(600);
		cloud.setRadiusPerTick(-(7.0F - cloud.getRadius()) / cloud.getDuration());
		cloud.addEffect(new MobEffectInstance(UGEffects.VIRULENCE, 100, 0));

		this.playSound(UGSoundEvents.GLOOMPER_FART.get(), 1.0F, 1.0F);
		this.level().addFreshEntity(cloud);
	}

	return super.hurtServer(level, source, amount);
}

public boolean canBeAffected(MobEffectInstance effectInstance) {
	if (effectInstance.getEffect().is(UGEffects.VIRULENCE)) {
		return false;
	} else return super.canBeAffected(effectInstance);
}

protected SoundEvent getHurtSound(DamageSource source) {
	return UGSoundEvents.GLOOMPER_HURT.get();
}

public boolean isInvulnerableTo(DamageSource source) {
	return this.isInvulnerable() && !source.is(DamageTypes.FELL_OUT_OF_WORLD) && !source.is(DamageTypes.CRAMMING);
}

public boolean skipAttackInteraction(Entity entityIn) {
	return entityIn instanceof Player player && this.hurt(this.level().damageSources().playerAttack(player), 0.0F);
}

public boolean hurt(DamageSource source, float amount) {
	if (this.isInvulnerableTo(source)) {
		return false;
	} else {
		if (this.isAlive() && !this.level().isClientSide) {
			this.discard();
			this.markHurt();
			this.onBroken(!source.isCreativePlayer());
		}
		return true;
	}
}

protected void doParticles() {
	if (this.level() instanceof ServerLevel serverLevel) {
		serverLevel.sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, this.getBlockForParticle().defaultBlockState()), this.getX(), this.getY() + (double) this.getBbHeight() / 1.5D, this.getZ(), 10, this.getBbWidth() / 4.0F, this.getBbHeight() / 4.0F, this.getBbWidth() / 4.0F, 0.05D);
	}
}

public boolean hurt(DamageSource source, float amount) {
	Entity entitySource = source.getEntity();
	if (entitySource instanceof LivingEntity && !this.isVehicle()) {
		if (entitySource instanceof Player) {
			if (!entitySource.isSpectator() && !((Player) entitySource).isCreative()) {
				this.setBoofloAttackTargetId(entitySource.getId());
			}
		} else {
			this.setBoofloAttackTargetId(entitySource.getId());
		}
	}
	float newCalculatedDamage = source.is(DamageTypes.IN_WALL) ? 0.5F : amount;
	if (super.hurt(source, source.getEntity() instanceof PuffBug ? 2.5F : newCalculatedDamage)) {
		if (this.isNoEndimationPlaying()) NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_HURT);
		return true;
	}
	return false;
}

protected void actuallyHurt(DamageSource damageSrc, float damageAmount) {
	Entity entitySource = damageSrc.getEntity();
	if (entitySource instanceof LivingEntity && !this.isVehicle()) {
		if (entitySource instanceof Player) {
			if (!entitySource.isSpectator() && !((Player) entitySource).isCreative()) {
				this.setBoofloAttackTargetId(entitySource.getId());
			}
		} else {
			this.setBoofloAttackTargetId(entitySource.getId());
		}
	}
	super.actuallyHurt(damageSrc, damageAmount);
}
